+    private static void putShutdownForRemovalMetadata(String nodeName, ClusterService clusterService) {
+        PlainActionFuture.<Void, RuntimeException>get(
+            fut -> putShutdownForRemovalMetadata(clusterService, nodeName, fut),
+            10,
+            TimeUnit.SECONDS
+        );
+    }
